/*!
 * The command model: every write is a [`Command`] (DD-15, D-5).
 *
 * A command carries a [`CommandId`] generated by the **caller** (the UI, an
 * importer or a test), so a retried call reuses the same ID. The engine
 * records the ID and the command's [`CommandOutcome`] in the same
 * transaction as the change. A command that was already applied changes
 * nothing and returns the outcome it had the first time, so a caller whose
 * first response was lost can retry and carry on (S-7). Importers and,
 * later, sync share this one write path.
 *
 * Reusing a [`CommandId`] for a *different* command is not detected: the
 * second command is treated as a replay of the first. A payload hash could
 * catch it; that is deferred (DD-15).
 *
 * ## Creating versus correcting
 *
 * The commands here only **add**: a set, an entry, a session, an exercise,
 * or a session's end time and deload mark. None of them changes or removes
 * something already logged; [`LogSet`] always appends a new set.
 *
 * Corrections (editing or deleting a set, removing an entry, deleting a
 * session, renaming an exercise or changing its scheme) are planned as
 * their own commands with the records PR. Verdicts need nothing from them,
 * since they are computed on read, but records are materialized (DD-14), so
 * every correction must also recompute the records it affects, in the same
 * transaction.
 */

use core::fmt;

use gymos_domain::{ExerciseId, SessionExerciseId, SessionId, SetId, Uuid};

use crate::commands::{
    AddExercise, CreateExercise, FinishSession, LogSet, SetDeload, StartSession,
};

/** Identifies one command, so that applying it twice changes nothing. */
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct CommandId(Uuid);

impl CommandId {
    /** Wraps a caller-generated UUID. */
    pub const fn from_uuid(uuid: Uuid) -> Self {
        Self(uuid)
    }

    /** The underlying UUID. */
    pub const fn as_uuid(self) -> Uuid {
        self.0
    }
}

impl fmt::Display for CommandId {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        fmt::Display::fmt(&self.0, f)
    }
}

/** One write, with the ID that makes it idempotent. */
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Command {
    /** Generated by the caller and reused on retry. */
    pub id: CommandId,
    /** What to do. */
    pub kind: CommandKind,
}

impl Command {
    /** Pairs a command ID with what to do. */
    pub fn new(id: CommandId, kind: impl Into<CommandKind>) -> Self {
        Self {
            id,
            kind: kind.into(),
        }
    }
}

/** Every write the engine accepts. */
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum CommandKind {
    /** Adds an exercise to the catalog. */
    CreateExercise(CreateExercise),
    /** Starts a session. */
    StartSession(StartSession),
    /** Adds an exercise entry to a session. */
    AddExercise(AddExercise),
    /**
     * Appends a new set to a session entry. It never changes an existing
     * set; correcting one is a separate command, planned with records.
     */
    LogSet(LogSet),
    /** Finishes a session, or corrects its end time. */
    FinishSession(FinishSession),
    /** Marks or unmarks a session as a deload. */
    SetDeload(SetDeload),
}

macro_rules! command_from {
    ($($variant:ident),* $(,)?) => {
        $(impl From<$variant> for CommandKind {
            fn from(command: $variant) -> Self {
                Self::$variant(command)
            }
        })*
    };
}

command_from!(
    CreateExercise,
    StartSession,
    AddExercise,
    LogSet,
    FinishSession,
    SetDeload
);

/**
 * What an applied command did.
 *
 * Stores keep it next to the [`CommandId`], and a replayed command returns
 * it again unchanged. There is deliberately no "already applied" variant:
 * the same request always gets the same answer.
 */
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CommandOutcome {
    /** The exercise was created with this ID. */
    ExerciseCreated(ExerciseId),
    /** The session was started with this ID. */
    SessionStarted(SessionId),
    /** The entry was added to the session with this ID. */
    ExerciseAdded(SessionExerciseId),
    /** The set was logged with this ID. */
    SetLogged(SetId),
    /** The session's end time was recorded. */
    SessionFinished,
    /** The session's deload mark was set as asked. */
    DeloadSet,
}
